/*
 * Chirpy service worker with automatic activation.
 * New deployments take control immediately instead of waiting for a user click.
 */
(() => {
  'use strict';

  importScripts('./assets/js/data/swconf.js');

  const { purge, interceptor } = swconf;

  self.addEventListener('install', (event) => {
    const precache = purge
      ? Promise.resolve()
      : caches.open(swconf.cacheName).then((cache) => cache.addAll(swconf.resources));

    event.waitUntil(precache.then(() => self.skipWaiting()));
  });

  self.addEventListener('activate', (event) => {
    const clearOldCaches = caches.keys().then((keys) =>
      Promise.all(
        keys.map((key) =>
          purge || key !== swconf.cacheName ? caches.delete(key) : undefined
        )
      )
    );

    event.waitUntil(clearOldCaches.then(() => self.clients.claim()));
  });

  self.addEventListener('message', (event) => {
    if (event.data === 'SKIP_WAITING') {
      self.skipWaiting();
    }
  });

  self.addEventListener('fetch', (event) => {
    if (event.request.headers.has('range')) {
      return;
    }

    event.respondWith(
      caches.match(event.request).then((cachedResponse) => {
        if (cachedResponse) {
          return cachedResponse;
        }

        return fetch(event.request).then((response) => {
          const requestUrl = event.request.url;
          const shouldCache = (() => {
            const url = new URL(requestUrl);
            const { pathname } = url;

            if (!url.protocol.startsWith('http')) {
              return false;
            }

            if (interceptor.urlPrefixes.some((prefix) => url.href.startsWith(prefix))) {
              return false;
            }

            if (interceptor.paths.some((path) => pathname.startsWith(path))) {
              return false;
            }

            return true;
          })();

          if (purge || event.request.method !== 'GET' || !shouldCache) {
            return response;
          }

          const responseForCache = response.clone();
          caches.open(swconf.cacheName).then((cache) => {
            cache.put(event.request, responseForCache);
          });

          return response;
        });
      })
    );
  });
})();
